package cl.nexbyte.siger.institucional.formulario;
import cl.nexbyte.siger.institucional.robustez.*;import cl.nexbyte.siger.institucional.archivos.ArchivoPrivado;
import java.nio.file.*;import java.security.*;import java.time.*;import java.util.*;

/** Productor SINTÉTICO en proceso. No conecta al formulario ni tiene cliente gubernamental. */
public final class IngresoDocumentalWindows {
 static final tools.jackson.databind.json.JsonMapper M=EntregaCompleta.lector();
 static String pem(Key key,String kind){return "-----BEGIN "+kind+" KEY-----\n"+Base64.getEncoder().encodeToString(key.getEncoded())+"\n-----END "+kind+" KEY-----\n";}
 static void write(Path p,byte[] b)throws Exception{Files.createFile(p);ArchivoPrivado.proteger(p);Files.write(p,b);}
 static EntregaCompleta entrega(String version,String type,boolean run,List<EntregaCompleta.Adjunto> attachments,PrivateKey signing){
  var c=M.createObjectNode();c.put("version",version);c.put("id",UUID.randomUUID().toString());c.put("recorridoId",UUID.randomUUID().toString());c.put("tipo",type);c.put("recibidaEn",Instant.now().toString());c.put("avisoVersion","QA_WINDOWS_SINTETICO");c.put("aceptaCanalDigital",!type.equals("NNA"));
  var data=c.putObject("datos");var fields=data.putObject("campos");fields.put("motivo","consulta");fields.put(type.equals("NNA")?"nna-story":"consulta-general-detalle","Relato completamente sintético de QA Windows");data.putArray("personas");data.putArray("instituciones");var ids=data.putArray("adjuntos");var descriptors=c.putArray("adjuntos");for(var a:attachments){ids.add(a.id().toString());descriptors.add(M.valueToTree(a));}
  var p=c.putArray("personas").addObject();p.put("id",type.equals("NNA")?"presentador-nna":"presentador-adulto");p.put("rol","PRESENTADOR");p.put("autenticada",type.equals("ADULTO_CU"));p.put("modulo11",run);if(run){p.put("runNumero","12345678");p.put("runDv","5");}else{p.putNull("runNumero");p.putNull("runDv");}p.put("estadoConsulta","NO_HABILITADO");p.putNull("consultadaEn");p.putNull("consultaRef");p.putObject("discrepancias");var attrs=p.putObject("atributos");String source=type.equals("ADULTO_CU")?"CLAVE_UNICA_USERINFO":"DECLARACION_CIUDADANA";
  for(var k:type.equals("ADULTO_CU")?List.of("runNumero","runDv","nombres","apellidos"):List.of("primerNombre","segundoNombre","primerApellido","segundoApellido")){var a=attrs.putObject(k);a.put("valor",k.equals("runNumero")?"12345678":k.equals("runDv")?"5":"SINTETICO");a.putNull("codigo");a.put("fuente",source);a.put("nivel",type.equals("ADULTO_CU")?"IDENTIDAD_AUTENTICADA":"DECLARADO_NO_CONTRASTADO");a.put("observadoEn",c.path("recibidaEn").asString());a.put("evidencia",UUID.randomUUID().toString());}
  var sources=M.createObjectNode();for(var person:c.path("personas"))sources.set(person.path("id").asString(),M.createArrayNode().add(person.path("atributos")).add(person.path("discrepancias")));String hash=EntregaCompleta.huella("CONTENIDO",c,M),provenance=EntregaCompleta.huella("PROCEDENCIA",sources,M);var proof=new ComprobanteDigital.Contenido("1.0",UUID.fromString(c.path("id").asString()),Instant.parse(c.path("recibidaEn").asString()),"CUSTODIA_PUBLICA",hash,provenance,"FORMULARIO_PUBLICO_DDN",c.path("avisoVersion").asString());return new EntregaCompleta(c,hash,provenance,ComprobanteDigital.firmar(proof,"qa-publico-windows",signing,M));
 }
 public static void main(String[] args){try{run(args);}catch(Exception e){System.out.println("{\"ok\":false,\"error\":\"INGRESO_QA_NO_COMPROBADO\",\"type\":\""+e.getClass().getSimpleName()+"\"}");System.exit(1);}}
 static void run(String[] args)throws Exception{
  var root=Path.of(args[0]).toAbsolutePath().normalize();if(!root.toString().matches("C:\\\\req\\\\testdata\\\\runtime-qa-[a-f0-9]{32}"))throw new IllegalArgumentException();ArchivoPrivado.validarAcceso(root);var fixtures=Path.of(args[1]);var secret=M.readTree(System.in);if(!secret.path("user").asString().equals("siger_windows_qa_app"))throw new IllegalArgumentException();
  var trust=new HashMap<String,PublicKey>();secret.path("trust").properties().forEach(e->trust.put(e.getKey(),ComprobanteDigital.publicPem(e.getValue().asString())));var own=new HashMap<String,PublicKey>();secret.path("own").properties().forEach(e->own.put(e.getKey(),ComprobanteDigital.publicPem(e.getValue().asString())));if(own.size()!=1)throw new IllegalArgumentException();String keyId=own.keySet().iterator().next();var privateKey=ComprobanteDigital.privatePem(secret.path("key").asString());var keys=KeyPairGenerator.getInstance("Ed25519").generateKeyPair();trust.put("qa-publico-windows",keys.getPublic());var all=new HashMap<String,String>();trust.forEach((k,v)->all.put(k,pem(v,"PUBLIC")));var config=Files.createDirectory(root.resolve("recepcion"));ArchivoPrivado.proteger(config);write(config.resolve("publico-trust.json"),M.writeValueAsBytes(all));
  String url="jdbc:mysql://127.0.0.1:3306/siger_institucional_windows_qa?sslMode=VERIFY_IDENTITY&fallbackToSystemTrustStore=false&trustCertificateKeyStoreUrl=file:/C:/req/config/siger-mysql-truststore.p12&trustCertificateKeyStoreType=PKCS12&trustCertificateKeyStorePassword=public-trust&connectTimeout=5000&socketTimeout=15000&characterEncoding=UTF-8";
  var results=new ArrayList<Object>();try(var db=new BaseJdbc(url,secret.path("user").asString(),secret.path("password").asString(),2);var files=new ArchivoInstitucional(root.resolve("archivo"))){
   if(!db.sql.queryForObject("SELECT DATABASE()",String.class).equals("siger_institucional_windows_qa"))throw new IllegalStateException();var receiver=new RecepcionInstitucionalJdbc(db,M,trust,keyId,privateKey,own,"COM",6,Clock.systemUTC());
   for(int i=0;i<4;i++){String type=i==0?"ADULTO_CU":i==1?"ADULTO_DECLARADO":"NNA",version=i==0?"1.0":"1.1";boolean run=i!=3;var attachments=new ArrayList<EntregaCompleta.Adjunto>();for(var name:List.of("tres-paginas.pdf","imagen.png")){var path=fixtures.resolve(name);String hash;try(var in=Files.newInputStream(path)){hash=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(in.readAllBytes()));}attachments.add(new EntregaCompleta.Adjunto(UUID.randomUUID(),name,Files.size(path),hash,name.endsWith("pdf")?"application/pdf":"image/png","VALIDADO"));}
    var e=entrega(version,type,run,attachments,keys.getPrivate());receiver.validarCompleta(e);for(var a:attachments)try(var in=Files.newInputStream(fixtures.resolve(a.nombre()))){files.guardar(e.id(),a,in);}var receipt=receiver.guardarCompleta(e,files);var repeat=receiver.guardarCompleta(e,files);if(!receipt.equals(repeat))throw new IllegalStateException();var lease=UUID.randomUUID();receiver.prepararConfirmacion(e.id(),lease);var ack=receiver.registroCompletoConservado(e,files);e.validarRegistro(ack,own,M);receiver.confirmacionEntregada(e.id());results.add(Map.of("version",version,"type",type,"run",run,"communication",receipt.registro().comunicacionId(),"operation",e.id(),"folio",receipt.registro().folio(),"ackVerified",true,"attachments",2));
   }
  }
  write(root.resolve("e2e-ingreso.json"),M.writerWithDefaultPrettyPrinter().writeValueAsBytes(Map.of("scope","PRODUCTOR_Y_ACK_SINTETICOS_EN_PROCESO_NO_PUBLICO_REAL","cases",results)));System.out.println(M.writeValueAsString(Map.of("ok",true,"root",root.toString(),"communications",4,"originals",8,"ackTransport","SIMULADO_EN_PROCESO","governmentCalls",0)));
 }
}
